3	import * as React from "react";
4	import { CircleCheck, CircleAlert, Info, X } from "lucide-react";
5	import { t } from "@/lib/i18n";
6	
7	type ToastTone = "success" | "alert" | "info";
8	
9	interface ToastItem {
10	  id: number;
11	  message: string;
12	  tone: ToastTone;
13	}
14	
15	interface ToastApi {
16	  /** Show a dismissible visual toast (also announced to screen readers). */
17	  toast: (message: string, tone?: ToastTone) => void;
18	  /** Announce a state change to screen readers only (no visual chrome). */
19	  announce: (message: string, assertive?: boolean) => void;
20	}
21	
22	const ToastContext = React.createContext<ToastApi | null>(null);
23	
24	const TONE: Record<ToastTone, { icon: typeof Info; className: string }> = {
25	  success: { icon: CircleCheck, className: "border-success text-success" },
26	  alert: { icon: CircleAlert, className: "border-alert text-alert" },
27	  info: { icon: Info, className: "border-primary text-primary" },
28	};
29	
30	export function ToastProvider({ children }: { children: React.ReactNode }) {
31	  const [toasts, setToasts] = React.useState<ToastItem[]>([]);
32	  const [politeMsg, setPoliteMsg] = React.useState("");
33	  const [assertiveMsg, setAssertiveMsg] = React.useState("");
34	  const nextId = React.useRef(0);
35	
36	  const remove = React.useCallback((id: number) => {
37	    setToasts((prev) => prev.filter((tItem) => tItem.id !== id));
38	  }, []);
39	
40	  const api = React.useMemo<ToastApi>(
41	    () => ({
42	      toast: (message, tone = "info") => {
43	        const id = nextId.current++;
44	        setToasts((prev) => [...prev, { id, message, tone }]);
45	        setPoliteMsg(message);
46	        window.setTimeout(() => remove(id), 6000);
47	      },
48	      announce: (message, assertive = false) => {
49	        // Reset first so identical consecutive messages still announce.
50	        if (assertive) {
51	          setAssertiveMsg("");
52	          window.requestAnimationFrame(() => setAssertiveMsg(message));
53	        } else {
54	          setPoliteMsg("");
55	          window.requestAnimationFrame(() => setPoliteMsg(message));
56	        }
57	      },
58	    }),
59	    [remove],
60	  );
61	
62	  return (
63	    <ToastContext.Provider value={api}>
64	      {children}
65	
66	      {/* Visible toast stack */}
67	      <div
68	        className="pointer-events-none fixed inset-x-0 bottom-4 z-50 flex flex-col items-center gap-2 px-4"
69	        // Each toast carries its own role=status; this wrapper is just layout.
70	      >
71	        {toasts.map(({ id, message, tone }) => {
72	          const { icon: Icon, className } = TONE[tone];
73	          return (
74	            <div
75	              key={id}
76	              role="status"
77	              className={[
78	                "pointer-events-auto flex w-full max-w-md items-start gap-2.5 rounded-card border-l-4 bg-surface px-4 py-3 shadow-md",
79	                className,
80	              ].join(" ")}
81	            >
82	              <Icon size={20} strokeWidth={2} aria-hidden="true" className="mt-0.5" />
83	              <p className="flex-1 text-base text-ink">{message}</p>
84	              <button
85	                type="button"
86	                onClick={() => remove(id)}
87	                aria-label={t("safety.close")}
88	                className="-m-1 rounded-sm p-1 text-ink-soft hover:text-ink"
89	              >
90	                <X size={18} strokeWidth={2} aria-hidden="true" />
91	              </button>
92	            </div>
93	          );
94	        })}
95	      </div>
96	
97	      {/* Screen-reader live regions (visually hidden) */}
98	      <div className="sr-only" aria-live="polite" aria-atomic="true">
99	        {politeMsg}
100	      </div>
101	      <div className="sr-only" aria-live="assertive" aria-atomic="true">
102	        {assertiveMsg}
103	      </div>
104	    </ToastContext.Provider>
105	  );
106	}
107	
108	export function useToast(): ToastApi {
109	  const ctx = React.useContext(ToastContext);
110	  if (!ctx) {
111	    throw new Error("useToast must be used within a ToastProvider");
112	  }
113	  return ctx;
114	}
